  scen=[('Müşteri hizmetleri yoğun e-ticaret firması için örnek çalışma senaryosu', 'Bir e-ticaret firmasının destek ekibi aynı soruları tekrar tekrar yanıtlıyor. Soru türleri listelenir, veri kaynakları incelenir. Örnek yaklaşımda ilk pilot, sık sorulan sorulara taslak yanıt üreten bir yardımcı olur; insan onayı zorunlu tutulur ve kişisel veri akışı hukuk danışmanıyla birlikte gözden geçirilir.'), ('Üretim firması için örnek çalışma senaryosu', 'Bir üretici belge ve raporlarını elle işliyor. Senaryolar arasında belge okuma, talep tahmini ve kalite kontrolü çıkar. Değer ve efor tablosunda belge işleme ilk sıraya alınır; veri hazırlığı ve pilot ölçütü yol haritasına yazılır.')],
  costRows=[['Model ve API kullanımı', 'Hesabı açan taraf, genellikle siz', 'Pilot ve sonrası kullanım yoğunluğuna göre değişir'], ['Danışmanlık bedeli', 'PakSoft’a', 'Görüşme, atölye ve rapor kapsamına göre belirlenir'], ['Veri hazırlığı', 'Siz veya PakSoft', 'Temizleme, birleştirme veya anonimleştirme ihtiyacı'], ['Pilot geliştirme', 'PakSoft’a', 'Seçilen senaryonun kapsamı']],
  factors=[('Departman sayısı', 'Daha fazla ekip, daha fazla görüşme demektir'), ('Veri durumu', 'Dağınık veya eksik veri değerlendirme süresini uzatır'), ('Hassas veri', 'Kişisel veri varsa ek koruma ve onay gerekir'), ('Mevcut sistemler', 'Entegrasyon gereken sistem sayısı'), ('Pilot beklentisi', 'Strateji sonrası pilot geliştirme istenip istenmediği')],
